#!/bin/bash
set -e
BASE="/userdata/system/dynamic/store-apps"
APPS="/userdata/roms/apps"
IMAGES="$APPS/images"
BACK="/userdata/system/dynamic-backup/store-apps-all-$(date +%Y%m%d-%H%M%S)"
echo "=== BATOCERA DYNAMIC APPS COMPLETO V1.0 ==="
command -v python3 >/dev/null || { echo "Python 3 nao encontrado."; exit 1; }
command -v flatpak >/dev/null || { echo "Flatpak nao encontrado."; exit 1; }
mkdir -p "$BASE" "$APPS" "$IMAGES" "$BACK"
[ -f "$APPS/gamelist.xml" ] && cp -a "$APPS/gamelist.xml" "$BACK/gamelist.xml"

python3 - <<'PY'
from pathlib import Path
import base64,io,zipfile,shutil,json,os,time,xml.etree.ElementTree as ET
appsdata=json.loads('{"prime": {"name": "Prime Video", "url": "https://www.primevideo.com/", "pkg": "", "icon": "", "cover": ""}, "netflix": {"name": "Netflix", "url": "https://www.netflix.com/browse", "pkg": "", "icon": "", "cover": ""}, "disney": {"name": "Disney+", "url": "https://www.disneyplus.com/", "pkg": "", "icon": "", "cover": ""}, "youtube": {"name": "YouTube", "url": "https://www.youtube.com/", "pkg": "", "icon": "", "cover": ""}, "globoplay": {"name": "Globoplay", "url": "https://globoplay.globo.com/", "pkg": "", "icon": "", "cover": ""}, "spotify": {"name": "Spotify", "url": "https://open.spotify.com/", "pkg": "", "icon": "", "cover": ""}, "youtube_music": {"name": "YouTube Music", "url": "https://music.youtube.com/", "pkg": "", "icon": "", "cover": ""}, "apple_music": {"name": "Apple Music", "url": "https://music.apple.com/br/new", "pkg": "", "icon": "", "cover": ""}, "deezer": {"name": "Deezer", "url": "https://www.deezer.com/br/", "pkg": "", "icon": "", "cover": ""}}')
base=Path("/userdata/system/dynamic/store-apps"); apps=Path("/userdata/roms/apps"); images=apps/"images"
images.mkdir(parents=True,exist_ok=True)
gamelist=apps/"gamelist.xml"
if gamelist.exists():
    try: tree=ET.parse(gamelist); root=tree.getroot()
    except Exception: root=ET.Element("gameList"); tree=ET.ElementTree(root)
else: root=ET.Element("gameList"); tree=ET.ElementTree(root)

for appid,a in appsdata.items():
    d=base/appid; ext=d/"extension"; profile=d/"profile"; d.mkdir(parents=True,exist_ok=True)
    stage=d/"extension-stage"; shutil.rmtree(stage,ignore_errors=True); stage.mkdir()
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(a["pkg"]))) as z: z.extractall(stage)
    shutil.rmtree(ext,ignore_errors=True); stage.rename(ext)
    pref=profile/"Default"/"Preferences"; pref.parent.mkdir(parents=True,exist_ok=True)
    p={}
    if pref.exists():
        try:p=json.loads(pref.read_text(encoding="utf-8"))
        except Exception:p={}
    p.setdefault("translate",{})["enabled"]=False
    tmp=pref.with_name("Preferences.tmp"); tmp.write_text(json.dumps(p,ensure_ascii=False),encoding="utf-8"); os.replace(tmp,pref)
    imgdata=a["cover"] or a["icon"]; imgname=appid+"-store.png"
    if imgdata:(images/imgname).write_bytes(base64.b64decode(imgdata))
    launch=d/"launch.sh"
    if launch.exists():
        backup=Path("/userdata/system/aura/backups")/str(time.time_ns())/appid
        backup.mkdir(parents=True,exist_ok=True)
        shutil.copy2(launch,backup/"launch.sh")
    launch.write_text('#!/bin/bash\n# Dynamic cursor v1.2\nexec bash /userdata/system/aura/payload/streaming-launch.sh '+appid+'\n',encoding="utf-8",newline="\n")
    ports=Path("/userdata/roms/ports"); ports.mkdir(parents=True,exist_ok=True)
    wrapper=ports/(a["name"]+" (Streaming Aura).sh")
    wrapper.write_text('#!/bin/bash\n# aura-streaming-v6\nexec bash "'+str(launch)+'"\n',encoding="utf-8",newline="\n")
    wrapper.chmod(0o755)
    pg=ports/"gamelist.xml"
    pt=ET.parse(pg) if pg.exists() else ET.ElementTree(ET.Element("gameList"))
    pr=pt.getroot(); relport='./'+wrapper.name
    entry=next((g for g in pr.findall('game') if g.findtext('path')==relport),None)
    if entry is None: entry=ET.SubElement(pr,'game')
    for key,value in {'path':relport,'name':a['name']+' (Streaming Aura)','desc':'Abra o serviço e entre na sua conta. Use teclado/mouse; Alt+F4 para sair.','image':'../apps/images/'+imgname}.items():
        node=entry.find(key)
        if node is None: node=ET.SubElement(entry,key)
        node.text=value
    pt.write(pg,encoding='UTF-8',xml_declaration=True)
    launch.chmod(0o755)
    appfile=apps/(a["name"]+".app")
    appfile.write_text("managed=batocera-dynamic-completo-v1.0\nname=%s\ntype=command\nexec=%s\n"%(a["name"],launch),encoding="utf-8",newline="\n")
    rel="./"+appfile.name
    g=next((x for x in root.findall("game") if (x.findtext("path") or "").strip()==rel),None)
    if g is None:g=ET.SubElement(root,"game")
    vals={"path":rel,"name":a["name"],"desc":"Adaptacao original incluida na Batocera Store 0.5.1.","developer":"Batocera Dynamic","genre":"Apps","image":"./images/"+imgname,"thumbnail":"./images/"+imgname}
    for k,v in vals.items():
        e=g.find(k)
        if e is None:e=ET.SubElement(g,k)
        e.text=v
tree.write(gamelist,encoding="UTF-8",xml_declaration=True)
PY
sync
echo "[OK] Dynamic Apps Completo V1.0 instalado: pacotes originais + logos + cursor V1.2."
echo "Atualize a lista de jogos ou reinicie o EmulationStation."
